using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Text;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
namespace EarthUnscripted.TerrainDraft.AuthoringJson {
 // Narrow authoring-fixture shim over the Unity-installed Newtonsoft package.
 // No new package/network dependency and no engine references.
 public readonly struct JsonElement {readonly JToken token;internal JsonElement(JToken value){token=value;}public JsonElement GetProperty(string name){if(!(token is JObject o)||!o.TryGetValue(name,StringComparison.Ordinal,out var value))throw new InvalidDataException("Missing authored field "+name);return new JsonElement(value);}public bool TryGetProperty(string name,out JsonElement value){if(token is JObject o&&o.TryGetValue(name,StringComparison.Ordinal,out var found)){value=new JsonElement(found);return true;}value=default;return false;}public IEnumerable<JsonElement> EnumerateArray(){if(!(token is JArray array))throw new InvalidDataException("Authored array required");return array.Select(p=>new JsonElement(p));}public float GetSingle()=>token.Value<float>();public double GetDouble()=>token.Value<double>();public int GetInt32()=>token.Value<int>();public bool GetBoolean()=>token.Value<bool>();public string GetString()=>token.Type==JTokenType.Null?null:token.Value<string>();public string GetRawText()=>token.ToString(Formatting.None);}
 public sealed class JsonDocument {public JsonElement RootElement{get;}JsonDocument(JToken token){RootElement=new JsonElement(token);}public static JsonDocument Parse(byte[] bytes){if(bytes==null||bytes.Length>64000000)throw new InvalidDataException("Authored JSON byte budget");using(var text=new StringReader(new UTF8Encoding(false,true).GetString(bytes)))using(var reader=new JsonTextReader(text){DateParseHandling=DateParseHandling.None,FloatParseHandling=FloatParseHandling.Double,MaxDepth=64})return new JsonDocument(JToken.Load(reader,new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error}));}}
 public sealed class JsonSerializerOptions {public bool WriteIndented;}
 public static class JsonSerializer {public static string Serialize(object value,JsonSerializerOptions options=null)=>JsonConvert.SerializeObject(value,options!=null&&options.WriteIndented?Formatting.Indented:Formatting.None,new JsonSerializerSettings{ReferenceLoopHandling=ReferenceLoopHandling.Error,FloatFormatHandling=FloatFormatHandling.DefaultValue});}
}
